    fn symbol_cache_prewarm_test_mutex() -> &'static Mutex<()> {
        static LOCK: OnceLock<Mutex<()>> = OnceLock::new();
        LOCK.get_or_init(|| Mutex::new(()))
    }

    fn write_symbol_cache_source(
        project: &std::path::Path,
        relative: &str,
        content: &str,
    ) -> PathBuf {
        let path = project.join(relative);
        std::fs::create_dir_all(path.parent().expect("source parent"))
            .expect("create source parent");
        std::fs::write(&path, content).expect("write source");
        path
    }

    fn persist_symbol_cache_fixture(
        project: &std::path::Path,
        storage: &std::path::Path,
        project_key: &str,
        sources: &[PathBuf],
    ) {
        crate::root_cache::configure_artifact_access(project, project_key, false);
        let mut parser = FileParser::new();
        for source in sources {
            parser.extract_symbols(source).expect("extract symbols");
        }
        let shared = parser.symbol_cache();
        let mut cache = shared.read().expect("read symbol cache").clone();
        cache.set_project_root(project.to_path_buf());
        crate::symbol_cache_disk::write_to_disk(&cache, storage, project_key)
            .expect("persist symbol cache fixture");
    }

    fn symbol_file(path: &std::path::Path) -> super::SearchIndexSymbolFile {
        let modified = std::fs::metadata(path)
            .expect("stat source")
            .modified()
            .expect("source mtime");
        (path.to_path_buf(), modified)
    }

    #[test]
    fn configure_symbol_cache_prewarm_evicts_finished_trees_without_changing_symbols() {
        let project = tempfile::tempdir().expect("create project dir");
        let sources = [
            write_symbol_cache_source(
                project.path(),
                "src/first.rs",
                "pub fn first() {}\npub struct First;\n",
            ),
            write_symbol_cache_source(
                project.path(),
                "src/second.rs",
                "pub fn second() -> bool { true }\npub enum Second { Value }\n",
            ),
        ];

        let mut baseline_parser = FileParser::new();
        let expected_symbols = sources
            .iter()
            .map(|path| {
                baseline_parser
                    .extract_symbols(path)
                    .expect("extract baseline symbols")
            })
            .collect::<Vec<_>>();

        let shared = Arc::new(RwLock::new(SymbolCache::new()));
        let mut prewarm_parser = FileParser::with_symbol_cache_generation(shared.clone(), Some(0));
        for (path, expected) in sources.iter().zip(&expected_symbols) {
            assert!(super::prewarm_symbol_cache_file(&mut prewarm_parser, path)
                .expect("prewarm symbols"));
            assert_eq!(
                prewarm_parser.parse_tree_cache_len(),
                0,
                "a finished prewarm file must not leave its parse tree resident"
            );

            let modified = std::fs::metadata(path)
                .expect("stat prewarmed source")
                .modified()
                .expect("source mtime");
            let cached_symbols = shared
                .read()
                .expect("read symbol cache")
                .get(path, modified)
                .expect("prewarm retains extracted symbols");
            assert_eq!(&cached_symbols, expected);
        }

        let cache = shared.read().expect("read final symbol cache");
        assert_eq!(cache.len(), sources.len());
        assert!(sources.iter().all(|path| cache.contains_key(path)));
    }

    fn symbol_cache_disk_lock_wait_allows_mutation(reset: bool) {
        let _guard = symbol_cache_prewarm_test_mutex()
            .lock()
            .unwrap_or_else(std::sync::PoisonError::into_inner);
        let project = tempfile::tempdir().expect("create project dir");
        let storage = tempfile::tempdir().expect("create storage dir");
        let project_key = "contended-prewarm";
        let source =
            write_symbol_cache_source(project.path(), "src/lib.rs", "pub fn edited() {}\n");
        crate::root_cache::configure_artifact_access(project.path(), project_key, false);
        let held_lock = crate::symbol_cache_disk::SymbolCacheLock::acquire(
            storage.path(),
            project_key,
            project.path(),
        )
        .expect("hold disk lock while prewarm persists");
        let shared = Arc::new(RwLock::new(SymbolCache::new()));
        let (waiting_tx, waiting_rx) = std::sync::mpsc::channel();
        let (done_tx, done_rx) = std::sync::mpsc::channel();
        let root = project.path().to_path_buf();
        let storage_dir = storage.path().to_path_buf();
        let files = vec![symbol_file(&source)];
        let writer_cache = shared.clone();
        let writer = std::thread::spawn(move || {
            crate::symbol_cache_disk::observe_next_lock_acquisition(waiting_tx);
            super::prewarm_symbol_cache_from_search_files(
                root,
                writer_cache,
                Some(storage_dir),
                project_key.to_string(),
                0,
                files,
                false,
            );
            done_tx.send(()).expect("report prewarm completion");
        });
        waiting_rx
            .recv_timeout(Duration::from_secs(30))
            .expect("prewarm should reach the contended disk lock");

        let (invalidated_tx, invalidated_rx) = std::sync::mpsc::channel();
        let watcher_cache = shared.clone();
        let watcher = std::thread::spawn(move || {
            let started = std::time::Instant::now();
            let mut cache = watcher_cache
                .write()
                .expect("watcher acquires cache write guard");
            if reset {
                cache.reset();
            } else {
                cache.invalidate(&source);
            }
            invalidated_tx
                .send(started.elapsed())
                .expect("report watcher invalidation");
        });
        // The held lock would keep a regressed writer waiting for the full 30 s
        // lock timeout, so a 10 s bound separates the cases even on a loaded runner.
        let invalidation = invalidated_rx.recv_timeout(Duration::from_secs(10));
        let writer_still_waiting = matches!(
            done_rx.try_recv(),
            Err(std::sync::mpsc::TryRecvError::Empty)
        );
        // Release the disk lock before asserting so a regression cannot strand either thread.
        drop(held_lock);
        done_rx
            .recv_timeout(Duration::from_secs(30))
            .expect("prewarm should finish after releasing the disk lock");
        writer.join().expect("prewarm thread");
        watcher.join().expect("watcher thread");

        assert!(
            writer_still_waiting,
            "disk writes must remain excluded by the held lock"
        );
        let elapsed = invalidation.expect("watcher invalidation blocked by disk lock wait");
        assert!(
            elapsed < Duration::from_secs(10),
            "watcher took {elapsed:?}"
        );
        assert_eq!(shared.read().expect("read invalidated cache").len(), 0);
        let disk = crate::symbol_cache_disk::read_from_disk(storage.path(), project_key);
        if reset {
            assert!(
                disk.is_none(),
                "stale prewarm must not persist after a reset"
            );
        } else {
            assert!(
                disk.expect("read persisted invalidation").is_empty(),
                "persistence must read the cache after the lock wait"
            );
        }
    }

