    /// With the escape hatch (`ram_overlay: false`) the borrowed snapshot is
    /// not reconciled and still lists the live checkout's `extra/phantom.ts`.
    /// The on-disk backstop must keep that path out of glob and aft_search
    /// and report that it dropped it.
    #[test]
    fn phantom_paths_backstop_drops_missing_paths_when_reconcile_is_off() {
        let probe = borrowed_older_checkout_probe(OlderCheckoutKind::SharedClone, Some(false));
        assert!(
            !probe.glob_lists_phantom(),
            "glob returned a path that is not on disk: {probe:#?}"
        );
        assert_eq!(
            probe.glob_missing_on_disk_dropped, 1,
            "glob must count the dropped phantom path: {probe:#?}"
        );
        assert!(
            !probe.search_by_name_mentions_phantom,
            "aft_search named a path that is not on disk: {probe:#?}"
        );
        assert!(
            probe.search_by_name_missing_on_disk_dropped >= 1,
            "aft_search must count the dropped phantom path: {probe:#?}"
        );
    }

    /// A borrowing checkout keeps its index current after bind: the watcher
    /// feeds its own edits into the RAM overlay, so grep finds a file created
    /// and a line added after the index reported ready.
    #[test]
    fn borrowed_checkout_edit_after_bind_is_found_by_grep() {
        let _watcher_guard = watcher_test_mutex()
            .lock()
            .unwrap_or_else(|poisoned| poisoned.into_inner());
        let _artifact_guard = artifact_owner_test_lock();
        let _env_guard = home_env_mutex();
        let _git_env = crate::test_env::hermetic_git_env_guard();
        let temp = tempfile::tempdir().unwrap();
        let temp_root = git_friendly_canonical(temp.path());
        let (owner, scratch, storage) = {
            // Only the borrowing checkout needs a real watcher.
            let _disable_watcher = EnvVarGuard::set("AFT_TEST_DISABLE_FILE_WATCHER", "1");
            older_checkout_beside_live_owner(&temp_root, OlderCheckoutKind::SharedClone)
        };
        let _enable_watcher = EnvVarGuard::remove("AFT_TEST_DISABLE_FILE_WATCHER");
        let _sync_watcher = EnvVarGuard::set("AFT_TEST_SYNC_FILE_WATCHER_START", "1");

        let ctx = test_context();
        let response = handle_configure_for_test(&configure_with_storage(&scratch, &storage), &ctx);
        assert!(
            response.success,
            "scratch configure failed: {:?}",
            response.data
        );
        ctx.mark_subc_bound();
        wait_for_search_index_ready(&ctx, Duration::from_secs(10));
        assert!(
            ctx.ram_overlay_active(),
            "the default config must reconcile and overlay a borrow-only root"
        );
        assert!(
            ctx.watcher_runtime_active(),
            "a borrow-only root must run a file watcher"
        );
        assert_eq!(
            grep_matches_and_status(&ctx, "AFTER_BIND_NEW_FILE_TOKEN"),
            (0, "Ready".to_string())
        );

        std::fs::write(
            scratch.join("after_bind.ts"),
            "export const AFTER_BIND_NEW_FILE_TOKEN = 4;\n",
        )
        .unwrap();
        let mut shared = std::fs::read_to_string(scratch.join("shared.ts")).unwrap();
        shared.push_str("export const AFTER_BIND_EDIT_TOKEN = 5;\n");
        std::fs::write(scratch.join("shared.ts"), shared).unwrap();

        let deadline = Instant::now() + Duration::from_secs(15);
        loop {
            crate::runtime_drain::drain_watcher_events(&ctx);
            let new_file = grep_matches_and_status(&ctx, "AFTER_BIND_NEW_FILE_TOKEN");
            let edit = grep_matches_and_status(&ctx, "AFTER_BIND_EDIT_TOKEN");
            let ready = (1, "Ready".to_string());
            if new_file == ready && edit == ready {
                break;
            }
            assert!(
                Instant::now() < deadline,
                "edits after bind never reached the borrowed index: new file {new_file:?}, edit {edit:?}"
            );
            std::thread::sleep(Duration::from_millis(50));
        }
        assert_eq!(
            grep_matches_and_status(&ctx, "OLDER_COMMIT_TOKEN"),
            (1, "Ready".to_string()),
            "the checkout's own pre-existing content stays searchable"
        );

        ctx.stop_watcher_runtime();
        ctx.mark_subc_unbound();
        ctx.cancel_unbound_artifact_work();
        owner.mark_subc_unbound();
        owner.cancel_unbound_artifact_work();
    }

    #[test]
    fn ram_overlay_worktree_rescan_rebuilds_overlay_instead_of_dropping_it() {
        let _artifact_guard = artifact_owner_test_lock();
        let _env_guard = home_env_mutex();
        let _git_env = crate::test_env::hermetic_git_env_guard();
        let _disable_watcher = EnvVarGuard::set("AFT_TEST_DISABLE_FILE_WATCHER", "1");
        let temp = tempfile::tempdir().unwrap();
        let (worktree, storage) = linked_worktree_with_pre_existing_drift(temp.path());
        let ctx = configure_borrowing_worktree(&worktree, &storage);

        // Apply a session edit to the overlay with `SearchIndex::update_file`,
        // the call the watcher drain makes for a changed path.
        let edited = std::fs::canonicalize(&worktree)
            .unwrap()
            .join("edited-this-session.ts");
        std::fs::write(&edited, "export const EDITED_THIS_SESSION_TOKEN = 7;\n").unwrap();
        ctx.search_index()
            .write()
            .unwrap_or_else(std::sync::PoisonError::into_inner)
            .as_mut()
            .expect("resident borrowed index")
            .update_file(&edited);
        assert_eq!(
            grep_matches_and_status(&ctx, "EDITED_THIS_SESSION_TOKEN"),
            (1, "Ready".to_string())
        );

        crate::runtime_drain::refresh_project_after_watcher_rescan(&ctx);
        let (matches, status) = grep_matches_and_status(&ctx, "EDITED_THIS_SESSION_TOKEN");
        assert_eq!(
            matches, 1,
            "the fallback walk answers while the snapshot reloads"
        );
        assert_ne!(status, "Ready", "no reconciled index is resident yet");

        wait_for_search_index_ready(&ctx, Duration::from_secs(10));
        assert_eq!(
            grep_matches_and_status(&ctx, "EDITED_THIS_SESSION_TOKEN"),
            (1, "Ready".to_string()),
            "the reloaded snapshot must rebuild the overlay from disk, not start empty"
        );
        for token in PRE_EXISTING_DRIFT_TOKENS {
            assert_eq!(
                grep_matches_and_status(&ctx, token),
                (1, "Ready".to_string()),
                "{token} must survive the rescan reload"
            );
        }
        ctx.mark_subc_unbound();
        ctx.cancel_unbound_artifact_work();
    }

    #[test]
    fn borrowed_search_load_bypasses_saturated_cold_build_limiter() {
        let root = tempfile::tempdir().expect("create search root");
        let storage = tempfile::tempdir().expect("create search storage");
        persist_search_index_fixture(root.path(), storage.path());
        let ctx = test_context();
        ctx.update_config(|config| {
            config.project_root = Some(root.path().to_path_buf());
            config.storage_dir = Some(storage.path().to_path_buf());
            config.indexes.trigram = true;
        });
        ctx.set_canonical_cache_root(root.path().to_path_buf());
        ctx.set_cache_role(true, None);
        ctx.set_cache_writer_capabilities(false, true);
        ctx.isolate_cold_build_limiter_for_test(2);
        let limiter = ctx.cold_build_limiter();
        let _held_permits = (0..2)
            .map(|permit_number| {
                crate::cold_build_limiter::acquire_blocking_while_with_test_limiter(
                    &limiter,
                    &format!("hold borrowed-load control permit {permit_number}"),
                    || true,
                )
                .expect("hold limiter permit")
            })
            .collect::<Vec<_>>();

        let starts = super::schedule_artifact_loads(&ctx, true, false);
        assert!(starts.0.is_some());
        assert!(starts.1.is_none());
        let search_rx = ctx
            .search_index_rx()
            .read()
            .unwrap_or_else(std::sync::PoisonError::into_inner)
            .as_ref()
            .expect("borrowed search receiver installed")
            .clone();
        let mut completion = crossbeam_channel::Select::new();
        completion.recv(&search_rx);
        assert!(super::start_artifact_loads(starts));
        // Channel readiness observes publication without consuming the index;
        // the normal drain still installs it. The held permits prove bypass,
        // not how fast Windows schedules the loader or reads its cache file.
        completion.ready();
        assert!(
            !search_rx.is_empty(),
            "borrowed loader must publish an index"
        );
        crate::runtime_drain::drain_build_completions(&ctx);
        assert!(ctx
            .search_index_rx()
            .read()
            .unwrap_or_else(std::sync::PoisonError::into_inner)
            .is_none());
        assert!(
            limiter.try_acquire().is_none(),
            "control permits remain held"
        );
        assert!(ctx
            .search_index()
            .read()
            .unwrap_or_else(std::sync::PoisonError::into_inner)
            .as_ref()
            .is_some_and(|index| index.ready));
    }

