    #[test]
    fn cold_configure_starts_callgraph_before_semantic() {
        let _artifact_guard = artifact_owner_test_lock();
        let _env_guard = home_env_mutex();
        let _git_env = crate::test_env::hermetic_git_env_guard();
        let _disable_watcher = EnvVarGuard::set("AFT_TEST_DISABLE_FILE_WATCHER", "1");
        let root = tempfile::tempdir().unwrap();
        let storage = tempfile::tempdir().unwrap();
        init_git_fixture(root.path());
        std::fs::write(
            root.path().join("lib.rs"),
            "pub fn entry() { leaf(); }\npub fn leaf() {}\n",
        )
        .unwrap();
        let server = CountingEmbeddingServer::start();
        let ctx = Arc::new(test_context());
        ctx.isolate_cold_build_limiter_for_test(2);
        let req = configure_request_with_params(json!({
            "project_root": root.path(),
            "harness": "opencode",
            "storage_dir": storage.path(),
            "config": [user_tier(json!({
                "indexes": { "trigram": true, "semantic": true, "callgraph": true },
                "semantic": {
                    "backend": "openai_compatible",
                    "model": "counting-test-embedding",
                    "base_url": server.base_url.clone(),
                    "timeout_ms": 5_000,
                    "max_batch_size": 64,
                    "max_files": 1_000
                }
            }))],
        }));

        let (_, events) = crate::logging::capture_index_events(|| {
            let response = handle_configure_for_test(&req, &ctx);
            assert!(response.success, "configure failed: {response:?}");
            super::drain_deferred_configure_maintenance(&ctx);
            server.release_responses();

            let deadline = Instant::now() + Duration::from_secs(30);
            loop {
                crate::runtime_drain::drain_search_index_events(&ctx);
                crate::runtime_drain::drain_callgraph_store_events(&ctx);
                crate::runtime_drain::drain_semantic_index_events(&ctx);
                let search_done = ctx.search_index_rx().read().unwrap().is_none();
                let callgraph_done = ctx.callgraph_store_rx().lock().is_none();
                let semantic_done = ctx.semantic_index_rx().lock().is_none();
                if search_done && callgraph_done && semantic_done {
                    break;
                }
                assert!(
                    Instant::now() < deadline,
                    "cold configure index builds did not settle"
                );
                std::thread::sleep(Duration::from_millis(5));
            }
        });

        let started = |plane: &str| {
            events
                .iter()
                .position(|line| {
                    line.contains("kind=build_started") && line.contains(&format!("plane={plane}"))
                })
                .unwrap_or_else(|| panic!("missing {plane} build_started event: {events:#?}"))
        };
        // Search is present but its start is not ordered against the callgraph:
        // the two workers are independent threads and nothing sequences their
        // first log line, so asserting search < callgraph is a scheduler-timing
        // bet (it lost under a parallel suite). The ordering mechanism under
        // test is the semantic gate on the callgraph's build_started.
        let _search_started = started("search");
        let callgraph_started = started("callgraph");
        let semantic_started = started("semantic");
        assert!(
            callgraph_started < semantic_started,
            "configure must admit callgraph before semantic: {events:#?}"
        );
    }

    /// Configure `root` with the given user tier and drain until no index
    /// build is in flight, returning the captured index log events.
    fn configure_and_settle_indexes(
        ctx: &AppContext,
        root: &Path,
        storage: &Path,
        user: Value,
    ) -> Vec<String> {
        let req = configure_request_with_params(json!({
            "project_root": root,
            "harness": "opencode",
            "storage_dir": storage,
            "config": [user_tier(user)],
        }));
        let (_, events) = crate::logging::capture_index_events(|| {
            let response = handle_configure_for_test(&req, ctx);
            assert!(response.success, "configure failed: {response:?}");
            super::drain_deferred_configure_maintenance(ctx);
            let deadline = Instant::now() + Duration::from_secs(30);
            loop {
                crate::runtime_drain::drain_search_index_events(ctx);
                crate::runtime_drain::drain_callgraph_store_events(ctx);
                crate::runtime_drain::drain_semantic_index_events(ctx);
                let search_done = ctx.search_index_rx().read().unwrap().is_none();
                let callgraph_done = ctx.callgraph_store_rx().lock().is_none();
                let semantic_done = ctx.semantic_index_rx().lock().is_none();
                if search_done && callgraph_done && semantic_done {
                    break;
                }
                assert!(
                    Instant::now() < deadline,
                    "configure index builds did not settle"
                );
                std::thread::sleep(Duration::from_millis(5));
            }
        });
        events
    }

    fn index_build_started(events: &[String], plane: &str) -> bool {
        events.iter().any(|line| {
            line.contains("kind=build_started") && line.contains(&format!("plane={plane}"))
        })
    }

    fn lifecycle_fixture() -> (tempfile::TempDir, tempfile::TempDir) {
        let root = tempfile::tempdir().unwrap();
        let storage = tempfile::tempdir().unwrap();
        init_git_fixture(root.path());
        std::fs::write(
            root.path().join("lib.rs"),
            "pub fn entry() { leaf(); }\npub fn leaf() {}\n",
        )
        .unwrap();
        (root, storage)
    }

    #[test]
    fn missing_local_onnx_runtime_reports_a_named_cause_without_rescheduling() {
        use crate::feature_status::{
            cause, local_semantic_platform_supported, observed_index_status, IndexEffective,
            IndexPlane,
        };
        let ctx = test_context();
        ctx.update_config(|config| {
            config.indexes.semantic = true;
            config.semantic.backend = crate::config::SemanticBackend::Fastembed;
        });
        // Nothing observed yet: enabled but not observed.
        assert!(super::missing_artifact_loads(&ctx).semantic);
        let observed = observed_index_status(&ctx, IndexPlane::Semantic);
        assert_eq!(observed.effective, IndexEffective::Unavailable);
        assert_eq!(
            observed.unavailable_reason.as_deref(),
            Some(cause::RUNTIME_NOT_OBSERVED)
        );

        *ctx.semantic_index_status().write().unwrap() =
            crate::context::SemanticIndexStatus::Failed(format!(
                "{} dlopen('libonnxruntime.so') failed",
                crate::semantic_index::ONNX_RUNTIME_MISSING_PREFIX
            ));
        // The configured value stays true; the lane is unavailable with a
        // named cause and no further build is scheduled.
        assert!(ctx.config().indexes.semantic);
        assert!(!super::missing_artifact_loads(&ctx).semantic);
        let observed = observed_index_status(&ctx, IndexPlane::Semantic);
        assert_eq!(observed.effective, IndexEffective::Unavailable);
        let expected = if local_semantic_platform_supported() {
            cause::ONNX_RUNTIME_UNAVAILABLE
        } else {
            cause::SEMANTIC_PLATFORM_UNSUPPORTED
        };
        assert_eq!(observed.unavailable_reason.as_deref(), Some(expected));

        // Another backend is not held back by a local-runtime failure.
        ctx.update_config(|config| {
            config.semantic.backend = crate::config::SemanticBackend::OpenAiCompatible;
        });
        assert!(super::missing_artifact_loads(&ctx).semantic);

        // A resolved-off index is off regardless of backend support.
        ctx.update_config(|config| {
            config.indexes.semantic = false;
            config.semantic.backend = crate::config::SemanticBackend::Fastembed;
        });
        assert_eq!(
            observed_index_status(&ctx, IndexPlane::Semantic),
            crate::feature_status::IndexObservation::off()
        );
    }

    #[test]
    fn every_enabled_index_starts_even_with_every_consumer_tool_disabled() {
        use crate::feature_status::{observed_index_status, IndexEffective, IndexPlane};
        let _artifact_guard = artifact_owner_test_lock();
        let _env_guard = home_env_mutex();
        let _git_env = crate::test_env::hermetic_git_env_guard();
        let _disable_watcher = EnvVarGuard::set("AFT_TEST_DISABLE_FILE_WATCHER", "1");
        let (root, storage) = lifecycle_fixture();
        let server = CountingEmbeddingServer::start();
        server.release_responses();
        let ctx = Arc::new(test_context());
        ctx.isolate_cold_build_limiter_for_test(2);
        // Index lifecycle is independent of registration: disabling every
        // consumer of the three indexes must not keep any of them from building.
        let events = configure_and_settle_indexes(
            &ctx,
            root.path(),
            storage.path(),
            json!({
                "indexes": { "trigram": true, "semantic": true, "callgraph": true },
                "disabled_tools": [
                    "aft_callgraph", "aft_inspect", "aft_search", "aft_zoom", "glob", "grep"
                ],
                "semantic": {
                    "backend": "openai_compatible",
                    "model": "counting-test-embedding",
                    "base_url": server.base_url.clone(),
                    "timeout_ms": 5_000,
                    "max_batch_size": 64,
                    "max_files": 1_000
                }
            }),
        );
        for plane in ["search", "callgraph", "semantic"] {
            assert!(
                index_build_started(&events, plane),
                "{plane} must start with its consumers disabled: {events:#?}"
            );
        }
        for plane in IndexPlane::ALL {
            assert_eq!(
                observed_index_status(&ctx, plane).effective,
                IndexEffective::Ready,
                "{plane:?} must be ready after its build settles"
            );
        }
    }

    #[test]
    fn evicted_trigram_index_with_a_valid_disk_cache_reports_ready() {
        use crate::feature_status::{cause, observed_index_status, IndexEffective, IndexPlane};
        let _artifact_guard = artifact_owner_test_lock();
        let _env_guard = home_env_mutex();
        let _git_env = crate::test_env::hermetic_git_env_guard();
        let _disable_watcher = EnvVarGuard::set("AFT_TEST_DISABLE_FILE_WATCHER", "1");
        let (root, storage) = lifecycle_fixture();
        let ctx = Arc::new(test_context());
        ctx.isolate_cold_build_limiter_for_test(2);
        configure_and_settle_indexes(
            &ctx,
            root.path(),
            storage.path(),
            json!({ "indexes": { "trigram": true, "semantic": false, "callgraph": false } }),
        );
        assert_eq!(
            observed_index_status(&ctx, IndexPlane::Trigram).effective,
            IndexEffective::Ready
        );

        // Idle eviction drops the resident index but keeps the persisted cache,
        // which the next query reloads: the lane stays usable.
        assert!(ctx.evict_idle_artifacts(), "trigram index should be idle");
        assert!(ctx.search_index().read().unwrap().is_none());
        assert_eq!(
            observed_index_status(&ctx, IndexPlane::Trigram).effective,
            IndexEffective::Ready,
            "an evicted index with a valid cache on disk is usable"
        );
        // Observing did not start the reload.
        assert!(ctx.search_index_rx().read().unwrap().is_none());

        // With nothing valid on disk, nothing is known about the index.
        let canonical_root = ctx.canonical_cache_root_opt().expect("canonical root");
        let key = ctx
            .cached_artifact_cache_key(&canonical_root)
            .expect("configure derived the artifact key");
        let cache_file =
            crate::search_index::resolve_cache_dir_with_key(&key, Some(storage.path()))
                .join("cache.bin");
        std::fs::write(&cache_file, b"not a trigram cache").unwrap();
        let observed = observed_index_status(&ctx, IndexPlane::Trigram);
        assert_eq!(observed.effective, IndexEffective::Unavailable);
        assert_eq!(
            observed.unavailable_reason.as_deref(),
            Some(cause::RUNTIME_NOT_OBSERVED)
        );
    }

    #[test]
    fn disabled_indexes_never_start_and_are_retired_on_reconfigure() {
        use crate::feature_status::{observed_index_status, IndexObservation, IndexPlane};
        let _artifact_guard = artifact_owner_test_lock();
        let _env_guard = home_env_mutex();
        let _git_env = crate::test_env::hermetic_git_env_guard();
        let _disable_watcher = EnvVarGuard::set("AFT_TEST_DISABLE_FILE_WATCHER", "1");
        let (root, storage) = lifecycle_fixture();
        let ctx = Arc::new(test_context());
        ctx.isolate_cold_build_limiter_for_test(2);

        // First bind with trigram and callgraph on, so there is something
        // running to retire.
        let events = configure_and_settle_indexes(
            &ctx,
            root.path(),
            storage.path(),
            json!({ "indexes": { "trigram": true, "semantic": false, "callgraph": true } }),
        );
        assert!(index_build_started(&events, "search"), "{events:#?}");
        assert!(index_build_started(&events, "callgraph"), "{events:#?}");
        assert!(ctx.search_index().read().unwrap().is_some());
        assert!(ctx.callgraph_store().read().unwrap().is_some());

        // Turning every index off retires what was running and starts nothing.
        let events = configure_and_settle_indexes(
            &ctx,
            root.path(),
            storage.path(),
            json!({ "indexes": { "trigram": false, "semantic": false, "callgraph": false } }),
        );
        assert!(ctx.search_index().read().unwrap().is_none());
        assert!(ctx.callgraph_store().read().unwrap().is_none());
        assert!(ctx.semantic_index().read().unwrap().is_none());
        for plane in IndexPlane::ALL {
            assert_eq!(observed_index_status(&ctx, plane), IndexObservation::off());
        }

        // A callgraph query against the disabled index refuses without
        // starting a build.
        let (response, query_events) = crate::logging::capture_index_events(|| {
            let navigation = RawRequest {
                id: "off-callers".to_string(),
                command: "callers".to_string(),
                lsp_hints: None,
                session_id: None,
                params: json!({"file": root.path().join("lib.rs"), "symbol": "leaf"}),
            };
            crate::commands::callers::handle_callers(&navigation, &ctx)
        });
        assert!(!response.success);
        assert_eq!(response.data["code"], json!("callgraph_off"));
        assert!(ctx.callgraph_store_rx().lock().is_none());
        assert!(ctx.callgraph_store().read().unwrap().is_none());
        let all_events = events
            .iter()
            .chain(query_events.iter())
            .cloned()
            .collect::<Vec<_>>();
        for plane in ["search", "callgraph", "semantic"] {
            assert!(
                !index_build_started(&all_events, plane),
                "disabled {plane} index must never start: {all_events:#?}"
            );
        }
    }

    #[test]
    fn obsolete_non_git_upgrade_waits_for_capacity_and_runs_once() {
        let _artifact_guard = artifact_owner_test_lock();
        let _env_guard = home_env_mutex();
        let _git_env = crate::test_env::hermetic_git_env_guard();
        let _watcher = EnvVarGuard::remove("AFT_TEST_DISABLE_FILE_WATCHER");
        let fixture = busy_obsolete_non_git_upgrade();
        let ctx = &fixture.ctx;
        let mut pending = ctx
            .take_parked_configure_tail()
            .expect("a refused upgrade must remain pending on the root");
        assert_eq!(pending.jobs.len(), 1);
        assert_eq!(
            pending.jobs.front().unwrap().stage,
            super::ConfigureMaintenanceStage::Callgraph
        );
        assert!(pending
            .jobs
            .front()
            .unwrap()
            .callgraph_upgrade_retry_at
            .is_some());
        assert!(!ctx.callgraph_cold_build_active());
        assert_eq!(ctx.callgraph_cold_build_spawn_count_for_test(), 0);
        pending.jobs.front_mut().unwrap().callgraph_upgrade_retry_at = Some(Instant::now());
        pending.replay_retry_cutoff = Some(Instant::now());
        while super::drain_deferred_configure_maintenance_unit(ctx, &mut pending) {}
        assert!(
            pending.callgraph_upgrade_pending(),
            "a still-full limiter must retain the upgrade for another tick"
        );
        pending.replay_retry_cutoff = None;
        ctx.park_configure_tail(pending);

        assert!(handle_configure_for_test(&fixture.request, ctx).success);
        super::drain_deferred_configure_maintenance(ctx);
        assert!(
            ctx.configure_callgraph_upgrade_pending(),
            "an equivalent bind must retain the project's pending upgrade"
        );

        let navigation = RawRequest {
            id: "pending-upgrade-navigation".into(),
            command: "callers".into(),
            lsp_hints: None,
            session_id: None,
            params: json!({"file": fixture.source, "symbol": "marker"}),
        };
        let response = crate::commands::callers::handle_callers(&navigation, ctx);
        assert!(!response.success);
        assert_eq!(response.data["code"], "callgraph_building");

        let (reached, release) = crate::context::install_callgraph_build_start_gate_for_test(
            ctx.callgraph_project_root().unwrap(),
        );
        drop(fixture.slots);
        pending = ctx.take_parked_configure_tail().unwrap();
        pending.jobs.front_mut().unwrap().callgraph_upgrade_retry_at = Some(Instant::now());
        pending.replay_retry_cutoff = Some(Instant::now());
        while super::drain_deferred_configure_maintenance_unit(ctx, &mut pending) {}
        release.send(()).ok();
        reached
            .recv_timeout(Duration::from_secs(5))
            .expect("freeing a slot must admit the pending upgrade");
        assert_eq!(ctx.callgraph_cold_build_spawn_count_for_test(), 1);
        let deadline = Instant::now() + Duration::from_secs(15);
        while ctx.callgraph_cold_build_active() {
            crate::runtime_drain::drain_callgraph_store_events(ctx);
            assert!(Instant::now() < deadline, "upgrade did not settle");
            std::thread::sleep(Duration::from_millis(5));
        }
        for _ in 0..3 {
            super::drain_deferred_configure_maintenance(ctx);
        }
        assert!(
            ctx.callgraph_store().read().unwrap().is_some(),
            "upgrade settled without a reader: denial={:?}, suspension={:?}",
            ctx.callgraph_store_build_denial(),
            ctx.callgraph_store_build_suspension()
        );
        assert_eq!(
            ctx.callgraph_cold_build_spawn_count_for_test(),
            1,
            "later maintenance must not rebuild the same upgrade twice"
        );
    }

    #[test]
    fn obsolete_non_git_upgrade_pending_unbind_cancels_retry() {
        let _artifact_guard = artifact_owner_test_lock();
        let _env_guard = home_env_mutex();
        let _git_env = crate::test_env::hermetic_git_env_guard();
        let _watcher = EnvVarGuard::remove("AFT_TEST_DISABLE_FILE_WATCHER");
        let fixture = busy_obsolete_non_git_upgrade();
        let ctx = &fixture.ctx;
        let pending = ctx
            .take_parked_configure_tail()
            .expect("a refused upgrade must remain pending until admission or unbind");
        assert!(pending
            .jobs
            .front()
            .unwrap()
            .callgraph_upgrade_retry_at
            .is_some());
        ctx.park_configure_tail(pending);
        ctx.mark_subc_unbound();
        assert_eq!(super::cancel_deferred_configure_maintenance(ctx), 1);
        drop(fixture.slots);
        super::drain_deferred_configure_maintenance(ctx);
        assert!(ctx.configure_tail_idle());
        assert!(matches!(
            ctx.schedule_callgraph_store_warm().0,
            CallgraphStoreAccess::Unavailable
        ));
        assert!(!ctx.callgraph_cold_build_active());
        assert!(ctx.callgraph_store().read().unwrap().is_none());
        assert_eq!(ctx.callgraph_cold_build_spawn_count_for_test(), 0);
        ctx.mark_subc_bound();
        super::drain_deferred_configure_maintenance(ctx);
        assert_eq!(
            ctx.callgraph_cold_build_spawn_count_for_test(),
            0,
            "a canceled pending upgrade must not survive a later bind without a new configure"
        );
    }

    #[test]
    fn obsolete_non_git_upgrade_pending_inspect_has_no_clean_dead_code() {
        let _artifact_guard = artifact_owner_test_lock();
        let _env_guard = home_env_mutex();
        let _git_env = crate::test_env::hermetic_git_env_guard();
        let _watcher = EnvVarGuard::remove("AFT_TEST_DISABLE_FILE_WATCHER");
        let fixture = busy_obsolete_non_git_upgrade();
        assert!(fixture.ctx.configure_callgraph_upgrade_pending());
        let inspect = RawRequest {
            id: "pending-upgrade-inspect".into(),
            command: "inspect".into(),
            lsp_hints: None,
            session_id: None,
            params: json!({"sections": ["dead_code"]}),
        };
        let response = crate::commands::inspect::handle_inspect_tool_call(&inspect, &fixture.ctx);
        assert_eq!(response.data["complete"], false, "{response:?}");
        assert!(
            response.data["summary"]["dead_code"]["count"].is_null(),
            "{response:?}"
        );
        let text = response.data["text"].as_str().unwrap();
        assert!(text.starts_with("PARTIAL"), "{text}");
        assert!(!text.contains("Dead code: 0"), "{text}");
        assert_eq!(fixture.ctx.callgraph_cold_build_spawn_count_for_test(), 0);
    }

    struct BusyObsoleteNonGitUpgrade {
        ctx: TestContext,
        _root: tempfile::TempDir,
        _storage: tempfile::TempDir,
        source: PathBuf,
        request: RawRequest,
        slots: Vec<crate::cold_build_limiter::ColdBuildPermit>,
    }

    fn busy_obsolete_non_git_upgrade() -> BusyObsoleteNonGitUpgrade {
        let root = tempfile::tempdir().unwrap();
        let storage = tempfile::tempdir().unwrap();
        let source = root.path().join("lib.rs");
        fs::write(&source, "pub fn marker() {}\n").unwrap();
        let ctx = test_context();
        ctx.isolate_cold_build_limiter_for_test(2);
        let slots = (0..2)
            .map(|_| ctx.take_cold_build_slot_for_test().unwrap())
            .collect();
        let request = configure_request_with_params(json!({
            "project_root": root.path(), "harness": "opencode", "storage_dir": storage.path(),
            "config": [user_tier(json!({
                "views": { "enabled": false },
                "indexes": { "trigram": false, "semantic": false, "callgraph": true },
                "inspect": { "diagnostics_timeout_ms": 10_000, "categories": {
                    "diagnostics": false, "todos": false, "dead_code": true,
                    "unused_exports": false, "duplicates": false,
                    "cycles": false, "complexity": false
                } }
            }))]
        }));
        assert!(handle_configure_for_test(&request, &ctx).success);
        let canonical = ctx.callgraph_project_root().unwrap();
        let (store, _) = crate::callgraph_store::CallGraphStore::cold_build_with_lease(
            ctx.callgraph_store_dir(),
            canonical.clone(),
            &[canonical.join("lib.rs")],
        )
        .unwrap();
        let database = store.sqlite_path().to_path_buf();
        drop(store);
        let conn = rusqlite::Connection::open(&database).unwrap();
        conn.execute(
            "UPDATE meta SET v = 'old-output-fingerprint' WHERE k = 'fingerprint'",
            [],
        )
        .unwrap();
        drop(conn);
        super::drain_deferred_configure_maintenance(&ctx);
        BusyObsoleteNonGitUpgrade {
            ctx,
            _root: root,
            _storage: storage,
            source,
            request,
            slots,
        }
    }

    #[test]
    fn non_git_obsolete_store_rebuilds_at_configure_through_maintenance_limiter() {
        let _artifact_guard = artifact_owner_test_lock();
        let _env_guard = home_env_mutex();
        let _git_env = crate::test_env::hermetic_git_env_guard();
        let _watcher = EnvVarGuard::remove("AFT_TEST_DISABLE_FILE_WATCHER");
        for obsolete_key in ["fingerprint", "schema_version"] {
            let root = tempfile::tempdir().unwrap();
            let storage = tempfile::tempdir().unwrap();
            let source = root.path().join("lib.rs");
            fs::write(&source, "pub fn marker() {}\n").unwrap();
            let ctx = test_context();
            ctx.isolate_cold_build_limiter_for_test(1);
            let request = configure_request_with_params(json!({
                "project_root": root.path(), "harness": "opencode", "storage_dir": storage.path(),
                "config": [user_tier(json!({
                    "views": { "enabled": false },
                    "indexes": { "trigram": false, "semantic": false, "callgraph": true }
                }))]
            }));
            assert!(handle_configure_for_test(&request, &ctx).success);
            let canonical = ctx.callgraph_project_root().unwrap();
            let (store, _) = crate::callgraph_store::CallGraphStore::cold_build_with_lease(
                ctx.callgraph_store_dir(),
                canonical.clone(),
                &[canonical.join("lib.rs")],
            )
            .unwrap();
            let database = store.sqlite_path().to_path_buf();
            drop(store);
            let conn = rusqlite::Connection::open(&database).unwrap();
            conn.execute(
                "UPDATE meta SET v = ?1 WHERE k = ?2",
                rusqlite::params![
                    if obsolete_key == "schema_version" {
                        "1"
                    } else {
                        "old-output-fingerprint"
                    },
                    obsolete_key,
                ],
            )
            .unwrap();
            drop(conn);
            let (reached, release) =
                crate::context::install_callgraph_build_start_gate_for_test(canonical);
            super::drain_deferred_configure_maintenance(&ctx);
            let scheduled = ctx.callgraph_store_rx().lock().is_some();
            // Always release the worker, including on an assertion failure.
            release.send(()).ok();
            assert!(
                scheduled,
                "obsolete {obsolete_key} must schedule a configure rebuild without navigation"
            );
            reached.recv_timeout(Duration::from_secs(5)).unwrap();
            let admissions = ctx.cold_build_limiter().admission_events();
            assert_eq!(admissions.len(), 1, "{admissions:?}");
            assert_eq!(
                admissions[0].class,
                crate::cold_build_limiter::ColdBuildAdmissionClass::Maintenance
            );
            let deadline = Instant::now() + Duration::from_secs(15);
            while ctx.callgraph_store_rx().lock().is_some() {
                crate::runtime_drain::drain_callgraph_store_events(&ctx);
                assert!(
                    Instant::now() < deadline,
                    "configure rebuild did not settle"
                );
                std::thread::sleep(Duration::from_millis(5));
            }
            assert!(ctx.callgraph_store().read().unwrap().is_some());
            assert!(
                !database.exists(),
                "obsolete generation must be collected after publication"
            );
        }
    }

    #[test]
    fn non_git_configure_defers_callgraph_until_navigation_and_reports_trip_terminally() {
        let _artifact_guard = artifact_owner_test_lock();
        let _env_guard = home_env_mutex();
        let _git_env = crate::test_env::hermetic_git_env_guard();
        let root = tempfile::tempdir().unwrap();
        let storage = tempfile::tempdir().unwrap();
        let source = root.path().join("lib.rs");
        std::fs::write(&source, "pub fn marker() {}\n").unwrap();
        let ctx = test_context();
        ctx.isolate_cold_build_limiter_for_test(1);
        let request = configure_request_with_params(json!({
            "project_root": root.path(),
            "harness": "opencode",
            "storage_dir": storage.path(),
            "config": [user_tier(json!({
                "indexes": { "trigram": false, "semantic": false, "callgraph": true }
            }))]
        }));
        assert!(handle_configure_for_test(&request, &ctx).success);
        super::drain_deferred_configure_maintenance(&ctx);

        let limiter = ctx.cold_build_limiter();
        assert!(
            limiter.admission_events().is_empty(),
            "non-git configure must not admit a callgraph cold-build job"
        );
        assert!(ctx.callgraph_store_rx().lock().is_none());
        assert!(
            !ctx.callgraph_store_dir()
                .join("build-breaker.sqlite")
                .exists(),
            "configure must not reach breaker attempt admission"
        );

        let canonical_root = ctx.callgraph_project_root().unwrap();
        let (reached, release) =
            crate::context::install_callgraph_build_start_gate_for_test(canonical_root);
        let navigation = RawRequest {
            id: "navigation".to_string(),
            command: "callers".to_string(),
            lsp_hints: None,
            session_id: None,
            params: json!({"file": source, "symbol": "marker"}),
        };
        let first = crate::commands::callers::handle_callers(&navigation, &ctx);
        assert!(!first.success);
        assert_eq!(first.data["code"], json!("callgraph_building"));
        reached
            .recv_timeout(Duration::from_secs(2))
            .expect("the first navigation query must enter the background build path");
        assert_eq!(limiter.admission_events().len(), 1);
        let second = crate::commands::callers::handle_callers(&navigation, &ctx);
        assert_eq!(second.data["code"], json!("callgraph_building"));
        assert_eq!(
            limiter.admission_events().len(),
            1,
            "the retry must join the existing single-flight build"
        );
        release.send(()).unwrap();
        let completion_deadline = Instant::now() + Duration::from_secs(10);
        while ctx.callgraph_store_rx().lock().is_some() {
            crate::runtime_drain::drain_callgraph_store_events(&ctx);
            assert!(
                Instant::now() < completion_deadline,
                "navigation-started callgraph build did not settle"
            );
            std::thread::sleep(Duration::from_millis(5));
        }

        let suspended_root = tempfile::tempdir().unwrap();
        let suspended_storage = tempfile::tempdir().unwrap();
        let suspended_source = suspended_root.path().join("lib.rs");
        std::fs::write(&suspended_source, "pub fn suspended_marker() {}\n").unwrap();
        let suspended_ctx = test_context();
        suspended_ctx.isolate_cold_build_limiter_for_test(1);
        let suspended_request = configure_request_with_params(json!({
            "project_root": suspended_root.path(),
            "harness": "opencode",
            "storage_dir": suspended_storage.path(),
            "config": [user_tier(json!({
                "indexes": { "trigram": false, "semantic": false, "callgraph": true }
            }))]
        }));
        assert!(handle_configure_for_test(&suspended_request, &suspended_ctx).success);
        super::drain_deferred_configure_maintenance(&suspended_ctx);
        let project_root = suspended_ctx.callgraph_project_root().unwrap();
        let breaker_key = crate::build_breaker::BreakerKey::new(
            project_root.display().to_string(),
            crate::build_breaker::BuildDomain::CallgraphCold,
            crate::callgraph_store::callgraph_corpus_fingerprint_for_test(&project_root, &[])
                .unwrap(),
        );
        let breaker = crate::build_breaker::BuildDeathBreaker::open(
            suspended_ctx
                .callgraph_store_dir()
                .join("build-breaker.sqlite"),
        )
        .unwrap();
        let now = crate::callgraph_store::unix_millis_now();
        for offset in 0..3 {
            let crate::build_breaker::BreakerAdmission::Admitted(attempt) =
                breaker.admit_at(&breaker_key, 0, now + offset).unwrap()
            else {
                panic!("breaker tripped before the third zero-credit death");
            };
            breaker
                .record_attributed_death_at(&breaker_key, &attempt.attempt_id, 0, 0, now + offset)
                .unwrap();
        }

        let suspended_navigation = RawRequest {
            id: "suspended-navigation".to_string(),
            command: "callers".to_string(),
            lsp_hints: None,
            session_id: None,
            params: json!({"file": suspended_source, "symbol": "suspended_marker"}),
        };
        let suspended =
            crate::commands::callers::handle_callers(&suspended_navigation, &suspended_ctx);
        assert!(!suspended.success);
        assert_eq!(suspended.data["code"], json!("callgraph_unavailable"));
        assert_eq!(
            suspended.data["index"]["callgraph"]["reason"],
            json!("build_suspended")
        );
        let message = suspended.data["message"].as_str().unwrap();
        assert!(
            message.starts_with("callers: build_suspended domain=callgraph_cold deaths=3 age_ms=")
        );
        assert!(message.ends_with(
            " reason=zero_credit_death_limit; run doctor reset-build-breaker to resume"
        ));
        assert!(
            suspended_ctx
                .cold_build_limiter()
                .admission_events()
                .is_empty(),
            "a terminal suspension must refuse before limiter admission"
        );
    }

    #[test]
    fn unbound_configure_cancellation_clears_gated_loaders_and_rebind_can_retry() {
        let _artifact_guard = artifact_owner_test_lock();
        let _env_guard = home_env_mutex();
        let _git_env = crate::test_env::hermetic_git_env_guard();
        let _disable_watcher = EnvVarGuard::set("AFT_TEST_DISABLE_FILE_WATCHER", "1");
        let root = tempfile::tempdir().unwrap();
        let storage = tempfile::tempdir().unwrap();
        init_git_fixture(root.path());
        let ctx = test_context();
        let req = configure_request_with_params(json!({
            "project_root": root.path(),
            "harness": "opencode",
            "storage_dir": storage.path(),
            "config": [user_tier(json!({
                "indexes": { "trigram": true, "semantic": false, "callgraph": false }
            }))]
        }));
        reset_configure_artifact_load_attempts_for_test();
        reset_configure_artifact_load_cancellations_for_test();

        assert!(handle_configure_for_test(&req, &ctx).success);
        assert!(ctx.search_index_rx().read().unwrap().is_some());
        ctx.mark_subc_unbound();
        assert!(super::cancel_deferred_configure_maintenance(&ctx) > 0);
        assert!(ctx.search_index_rx().read().unwrap().is_none());
        assert!(!ctx.configure_tail_has_work());
        let cancel_deadline = Instant::now() + Duration::from_secs(2);
        while configure_artifact_load_cancellations_for_test() == 0 {
            assert!(
                Instant::now() < cancel_deadline,
                "cancelled artifact loader did not observe its disconnected gate"
            );
            std::thread::yield_now();
        }
        assert_eq!(
            configure_artifact_load_attempts_for_test(),
            0,
            "cancelling a gated configure must not start its artifact loader"
        );

        assert!(handle_configure_for_test(&req, &ctx).success);
        assert!(ctx.search_index_rx().read().unwrap().is_some());
        ctx.mark_subc_bound();
        super::drain_deferred_configure_maintenance(&ctx);
        let deadline = Instant::now() + Duration::from_secs(2);
        while configure_artifact_load_attempts_for_test() == 0 {
            assert!(
                Instant::now() < deadline,
                "rebind did not replace the cancelled artifact loader"
            );
            std::thread::sleep(Duration::from_millis(5));
        }
    }

    #[test]
    fn artifact_worker_rechecks_lifecycle_after_its_start_gate() {
        let _artifact_guard = artifact_owner_test_lock();
        let _env_guard = home_env_mutex();
        let _git_env = crate::test_env::hermetic_git_env_guard();
        let _disable_watcher = EnvVarGuard::set("AFT_TEST_DISABLE_FILE_WATCHER", "1");
        struct ResetPostGateDelay;
        impl Drop for ResetPostGateDelay {
            fn drop(&mut self) {
                set_configure_artifact_post_gate_delay_for_test(0);
            }
        }
        let _reset = ResetPostGateDelay;

        let root = tempfile::tempdir().unwrap();
        let storage = tempfile::tempdir().unwrap();
        init_git_fixture(root.path());
        let req = configure_request_with_params(json!({
            "project_root": root.path(),
            "harness": "opencode",
            "storage_dir": storage.path(),
            "config": [user_tier(json!({
                "indexes": { "trigram": true, "semantic": false, "callgraph": false }
            }))]
        }));
        let ctx = Arc::new(test_context());
        reset_configure_artifact_load_attempts_for_test();
        reset_configure_artifact_load_cancellations_for_test();
        set_configure_artifact_post_gate_delay_for_test(500);

        assert!(handle_configure_for_test(&req, &ctx).success);
        ctx.mark_subc_bound();
        let drain_ctx = Arc::clone(&ctx);
        let drain = std::thread::spawn(move || {
            super::drain_deferred_configure_maintenance(&drain_ctx);
        });

        let reached_deadline = Instant::now() + Duration::from_secs(2);
        while configure_artifact_post_gate_reached_for_test() == 0 {
            assert!(
                Instant::now() < reached_deadline,
                "artifact worker did not cross its start gate"
            );
            std::thread::yield_now();
        }
        ctx.mark_subc_unbound();
        super::cancel_deferred_configure_maintenance(&ctx);
        release_configure_artifact_post_gate_for_test();
        drain.join().unwrap();

        let cancel_deadline = Instant::now() + Duration::from_secs(2);
        while configure_artifact_load_cancellations_for_test() == 0 {
            assert!(
                Instant::now() < cancel_deadline,
                "worker did not reject the now-unbound lifecycle"
            );
            std::thread::yield_now();
        }
        // The per-root count: another test's background load in this libtest
        // process would otherwise be read as this worker having started one.
        assert_eq!(
            configure_artifact_load_attempts_for_root_for_test(root.path()),
            0
        );
        assert!(ctx.search_index_rx().read().unwrap().is_none());
    }

    #[test]
    fn superseded_configure_tail_does_not_cancel_current_artifact_receiver() {
        let _artifact_guard = artifact_owner_test_lock();
        let _env_guard = home_env_mutex();
        let _git_env = crate::test_env::hermetic_git_env_guard();
        let _disable_watcher = EnvVarGuard::set("AFT_TEST_DISABLE_FILE_WATCHER", "1");
        let _delay = EnvVarGuard::set("AFT_TEST_CONFIGURE_DEFERRED_MAINTENANCE_DELAY_MS", "500");
        reset_configure_deferred_delay_reached_for_test();

        let root = tempfile::tempdir().unwrap();
        let storage = tempfile::tempdir().unwrap();
        init_git_fixture(root.path());
        let req = configure_request_with_params(json!({
            "project_root": root.path(),
            "harness": "opencode",
            "storage_dir": storage.path(),
            "config": [user_tier(json!({
                "indexes": { "trigram": true, "semantic": false, "callgraph": false }
            }))]
        }));
        let ctx = Arc::new(test_context());
        assert!(handle_configure_for_test(&req, &ctx).success);
        ctx.mark_subc_bound();

        let drain_ctx = Arc::clone(&ctx);
        let drain = std::thread::spawn(move || {
            super::drain_deferred_configure_maintenance(&drain_ctx);
        });
        let reached_deadline = Instant::now() + Duration::from_secs(2);
        while configure_deferred_delay_reached_for_test() == 0 {
            assert!(
                Instant::now() < reached_deadline,
                "configure tail did not reach the controlled delay"
            );
            std::thread::yield_now();
        }

        let current_generation = ctx.advance_configure_generation();
        let current_persist_epoch = ctx.next_search_persist_epoch();
        let (current_tx, current_rx) = crossbeam_channel::unbounded();
        ctx.install_search_index_rx(current_rx, current_generation);
        drain.join().unwrap();

        assert!(
            ctx.search_index_rx().read().unwrap().is_some(),
            "a superseded configure tail must not clear the current generation's receiver"
        );
        assert_eq!(
            ctx.search_persist_epoch_flag().current(),
            current_persist_epoch,
            "a stale configure tail must not invalidate a newer worker's persistence epoch"
        );
        drop(current_tx);
        ctx.search_index_rx().write().unwrap().take();
    }

