    /// A release bumps every package's `version`, and adding a dependency
    /// rewrites `dependencies`. Neither is read by the module resolver, so the
    /// reconfigure stays equivalent and keeps the callgraph store.
    #[test]
    fn writer_reconfigure_after_version_bump_keeps_callgraph_store() {
        let _artifact_guard = artifact_owner_test_lock();
        let _env_guard = home_env_mutex();
        let _git_env = crate::test_env::hermetic_git_env_guard();
        let _disable_watcher = EnvVarGuard::set("AFT_TEST_DISABLE_FILE_WATCHER", "1");
        let root = tempfile::tempdir().unwrap();
        let storage = tempfile::tempdir().unwrap();
        init_git_fixture(root.path());
        write_workspace_manifest(
            root.path(),
            r#"{"name":"@ws/pkg-a","version":"1.0.0","main":"index.ts"}"#,
        );
        let ctx = test_context();
        let request = callgraph_only_configure_request(root.path(), storage.path());

        assert!(handle_configure_for_test(&request, &ctx).success);
        assert!(ctx.callgraph_writer(), "a main checkout owns its callgraph");
        assert_eq!(ctx.pending_callgraph_store_force_token(), None);
        let generation = ctx.configure_generation();

        write_workspace_manifest(
            root.path(),
            r#"{"name":"@ws/pkg-a","version":"1.0.1","main":"index.ts","dependencies":{"left-pad":"^1.3.0"}}"#,
        );
        assert!(handle_configure_for_test(&request, &ctx).success);
        assert_eq!(
            ctx.configure_generation(),
            generation,
            "a version bump must leave the configure equivalent"
        );
        assert_eq!(
            ctx.pending_callgraph_store_force_token(),
            None,
            "a version bump must not force a callgraph rebuild"
        );
    }

    /// An `exports` change does move module resolution, but only for the files
    /// that import the package. The reconfigure hands the changed manifest to
    /// the incremental refresh instead of forcing a rebuild.
    #[test]
    fn writer_reconfigure_after_exports_change_refreshes_manifest_instead_of_rebuilding() {
        let _artifact_guard = artifact_owner_test_lock();
        let _env_guard = home_env_mutex();
        let _git_env = crate::test_env::hermetic_git_env_guard();
        let _disable_watcher = EnvVarGuard::set("AFT_TEST_DISABLE_FILE_WATCHER", "1");
        let root = tempfile::tempdir().unwrap();
        let storage = tempfile::tempdir().unwrap();
        init_git_fixture(root.path());
        write_workspace_manifest(
            root.path(),
            r#"{"name":"@ws/pkg-a","exports":{".":"./a.ts"}}"#,
        );
        std::fs::write(
            root.path().join("packages/pkg-a/a.ts"),
            "export function leaf() { oldLeaf(); }\nfunction oldLeaf() {}\n",
        )
        .unwrap();
        std::fs::write(
            root.path().join("packages/pkg-a/b.ts"),
            "export function leaf() { newLeaf(); }\nfunction newLeaf() {}\n",
        )
        .unwrap();
        std::fs::write(
            root.path().join("entry.ts"),
            "import { leaf } from '@ws/pkg-a';\nexport function entry() { leaf(); }\n",
        )
        .unwrap();
        std::fs::write(
            root.path().join("package.json"),
            r#"{"workspaces":["packages/*"]}"#,
        )
        .unwrap();
        let canonical_root = std::fs::canonicalize(root.path()).unwrap();
        let worker = crate::callgraph_store::isolated_callgraph_refresh_worker_for_test(
            canonical_root.clone(),
        );
        crate::callgraph_store::set_callgraph_refresh_worker_test_seam(
            canonical_root.clone(),
            Duration::ZERO,
            false,
        );
        let ctx = test_context();
        let request = callgraph_only_configure_request(root.path(), storage.path());

        assert!(handle_configure_for_test(&request, &ctx).success);
        assert!(ctx.callgraph_writer(), "a main checkout owns its callgraph");
        ctx.ensure_callgraph_store()
            .expect("build the callgraph store")
            .expect("a writer root builds its store on demand");
        assert!(
            matches!(
                ctx.callgraph_store_for_ops(),
                crate::context::CallgraphStoreAccess::Ready(_)
            ),
            "the published store answers before the manifest changes"
        );

        write_workspace_manifest(
            root.path(),
            r#"{"name":"@ws/pkg-a","exports":{".":"./b.ts"}}"#,
        );
        // Hold the refresh worker once it has taken the batch, so the query
        // below runs while the importers are not yet re-resolved.
        let (held, release) = crate::callgraph_store::install_callgraph_refresh_worker_test_gate(
            canonical_root.clone(),
        );
        assert!(handle_configure_for_test(&request, &ctx).success);
        assert_eq!(
            ctx.pending_callgraph_store_force_token(),
            None,
            "an exports change must refresh importers, not force a rebuild"
        );
        held.recv_timeout(Duration::from_secs(60))
            .expect("the fixture refresh worker hung before taking the changed manifest");
        let manifest = canonical_root.join("packages/pkg-a/package.json");
        assert!(
            crate::callgraph_store::callgraph_refresh_worker_test_paths(&canonical_root)
                .contains(&manifest)
        );
        assert!(
            matches!(
                ctx.callgraph_store_for_ops(),
                crate::context::CallgraphStoreAccess::Building
            ),
            "a query during the refresh must not be answered from the pre-refresh store"
        );
        release.send(()).unwrap();
        assert!(
            worker.wait(Duration::from_secs(60)),
            "the fixture refresh worker hung"
        );
        assert!(
            !ctx.callgraph_catch_up_outstanding(),
            "the settled refresh must release queries"
        );
        assert!(
            matches!(
                ctx.callgraph_store_for_ops(),
                crate::context::CallgraphStoreAccess::Ready(_)
            ),
            "once the refresh settles the store answers again"
        );
        let crate::context::CallgraphStoreAccess::Ready(store) = ctx.callgraph_store_for_ops()
        else {
            panic!("settled store must be ready");
        };
        let tree = store
            .call_tree(std::path::Path::new("entry.ts"), "entry", 2)
            .unwrap();
        assert_eq!(
            tree.children[0].children[0].name, "newLeaf",
            "manifest refresh must re-resolve the importer to b.ts"
        );
        crate::callgraph_store::clear_callgraph_refresh_worker_test_seam(&canonical_root);
    }

    #[test]
    fn read_only_worktree_reconfigure_never_mints_unfulfillable_callgraph_force_token() {
        let _artifact_guard = artifact_owner_test_lock();
        let _env_guard = home_env_mutex();
        let _git_env = crate::test_env::hermetic_git_env_guard();
        let _disable_watcher = EnvVarGuard::set("AFT_TEST_DISABLE_FILE_WATCHER", "1");
        let temp = tempfile::tempdir().unwrap();
        let storage = temp.path().join("storage");
        let main = temp.path().join("main");
        init_git_fixture(&main);
        let worktree = temp.path().join("worktree");
        let mut worktree_command = Command::new("git");
        assert!(
            crate::test_env::apply_hermetic_git_env(worktree_command.arg("-C").arg(&main))
                .args(["worktree", "add", "--detach", "--quiet"])
                .arg(&worktree)
                .arg("HEAD")
                .status()
                .unwrap()
                .success()
        );
        write_workspace_manifest(&worktree, "{}");
        let ctx = test_context();
        let request = callgraph_only_configure_request(&worktree, &storage);

        assert!(handle_configure_for_test(&request, &ctx).success);
        assert!(
            !ctx.callgraph_writer(),
            "a linked worktree borrows the owner's callgraph read-only"
        );

        // A different storage directory is a different callgraph store, so the
        // reconfigure is not equivalent for the callgraph lane.
        let moved_storage = temp.path().join("moved-storage");
        let moved = callgraph_only_configure_request(&worktree, &moved_storage);
        assert!(handle_configure_for_test(&moved, &ctx).success);
        assert!(
            !ctx.callgraph_writer(),
            "the worktree still borrows its owner's callgraph read-only"
        );
        assert_eq!(
            ctx.pending_callgraph_store_force_token(),
            None,
            "a read-only root cannot fulfil a force token, so reconfigure must not mint one"
        );
    }

    #[test]
    fn equivalent_reconfigure_keeps_warm_work_adopted_and_idempotent() {
        let _env_guard = home_env_mutex();
        let _git_env = crate::test_env::hermetic_git_env_guard();
        let _disable_watcher = EnvVarGuard::set("AFT_TEST_DISABLE_FILE_WATCHER", "1");
        let temp = tempfile::tempdir().unwrap();
        let storage = tempfile::tempdir().unwrap();
        init_git_fixture(temp.path());
        let ctx = test_context();
        let req = configure_request_with_params(json!({
            "project_root": temp.path(),
            "harness": "opencode",
            "storage_dir": storage.path(),
            "config": [user_tier(json!({
                "indexes": { "trigram": false, "semantic": false, "callgraph": false }
            }))]
        }));

        let first = handle_configure_for_test(&req, &ctx);
        assert!(first.success);
        super::drain_deferred_configure_maintenance(&ctx);

        let generation_after_first = ctx.configure_generation();
        assert_eq!(
            ctx.backup().lock().disk_io_count_for_tests(),
            0,
            "initial configure maintenance must not inspect backup directories"
        );
        let tsconfig_clear_generation_after_first =
            ctx.tsconfig_membership_clear_generation_for_test();
        let filter_rebuilds_after_first = ctx.filter_registry_rebuild_count_for_test();
        let artifact_derivations_after_first = ctx.artifact_cache_key_derivation_count_for_test();
        assert_eq!(
            artifact_derivations_after_first, 0,
            "configure should not derive an unused artifact key when artifact-backed features are disabled"
        );
        for _ in 0..5 {
            let response = handle_configure_for_test(&req, &ctx);
            assert!(response.success);
            super::drain_deferred_configure_maintenance(&ctx);
        }

        assert_eq!(
            ctx.backup().lock().disk_io_count_for_tests(),
            0,
            "equivalent configures must not inspect backup directories"
        );
        assert!(ctx.search_index_rx().read().unwrap().is_none());
        assert!(ctx.semantic_index_rx().lock().is_none());
        assert!(ctx.callgraph_store_rx().lock().is_none());
        assert_eq!(
            ctx.tsconfig_membership_clear_generation_for_test(),
            tsconfig_clear_generation_after_first,
            "equivalent rebind must keep the tsconfig-membership cache hot"
        );
        assert_eq!(
            ctx.filter_registry_rebuild_count_for_test(),
            filter_rebuilds_after_first,
            "equivalent rebind must not rebuild the TOML filter registry"
        );
        assert_eq!(
            ctx.artifact_cache_key_derivation_count_for_test(),
            artifact_derivations_after_first,
            "equivalent rebind must reuse the artifact cache key"
        );
        // Load-bearing: in-flight build workers publish only while the
        // generation flag equals their spawn generation. If equivalent
        // rebinds advanced it, every rebind during a long build would
        // silently discard the build's result at completion.
        assert_eq!(ctx.configure_generation(), generation_after_first);

        // A genuinely different warm config must still advance (this is what
        // cancels superseded in-flight builds).
        let changed = configure_request_with_params(json!({
            "project_root": temp.path(),
            "harness": "opencode",
            "config": [user_tier(json!({
                "indexes": { "trigram": true, "semantic": false, "callgraph": false }
            }))]
        }));
        let response = handle_configure_for_test(&changed, &ctx);
        assert!(response.success);
        super::drain_deferred_configure_maintenance(&ctx);
        assert_eq!(ctx.configure_generation(), generation_after_first + 1);
        assert!(
            ctx.config().indexes.trigram,
            "changed config must apply fully"
        );
        assert_eq!(
            ctx.tsconfig_membership_clear_generation_for_test(),
            tsconfig_clear_generation_after_first + 1
        );
        assert_eq!(
            ctx.filter_registry_rebuild_count_for_test(),
            filter_rebuilds_after_first + 1
        );
    }

    #[test]
    fn equivalent_reconfigure_replays_new_sessions_but_not_same_session_rebinds() {
        let _env_guard = home_env_mutex();
        let _git_env = crate::test_env::hermetic_git_env_guard();
        let _disable_watcher = EnvVarGuard::set("AFT_TEST_DISABLE_FILE_WATCHER", "1");
        super::reset_configure_replay_session_calls_for_test();
        let temp = tempfile::tempdir().unwrap();
        let storage = tempfile::tempdir().unwrap();
        init_git_fixture(temp.path());
        let ctx = test_context();
        let params = json!({
            "project_root": temp.path(),
            "harness": "opencode",
            "storage_dir": storage.path(),
            "config": [user_tier(json!({
                "indexes": { "trigram": false, "semantic": false, "callgraph": false }
            }))]
        });

        let session_a = configure_request_with_session(params.clone(), "session-a");
        let response = handle_configure_for_test(&session_a, &ctx);
        assert!(response.success);
        super::drain_deferred_configure_maintenance(&ctx);
        assert_eq!(super::configure_replay_session_calls_for_test(), 1);
        assert_eq!(ctx.backup().lock().disk_io_count_for_tests(), 0);

        let response = handle_configure_for_test(&session_a, &ctx);
        assert!(response.success);
        super::drain_deferred_configure_maintenance(&ctx);
        assert_eq!(
            super::configure_replay_session_calls_for_test(),
            1,
            "equivalent rebind for an already-bound session should skip replay"
        );

        let session_b = configure_request_with_session(params, "session-b");
        let response = handle_configure_for_test(&session_b, &ctx);
        assert!(response.success);
        super::drain_deferred_configure_maintenance(&ctx);
        assert_eq!(
            super::configure_replay_session_calls_for_test(),
            2,
            "a new session on an equivalent warm root still needs session replay"
        );
        assert_eq!(
            ctx.backup().lock().disk_io_count_for_tests(),
            0,
            "a fresh-session bind must not inspect backup directories"
        );
    }

